const KEY='setmate-v1';
const initial={person:'You',unit:'lb',machines:[{id:'leg-press',name:'Leg press',group:'Legs'},{id:'chest-press',name:'Chest press',group:'Chest'},{id:'lat-pulldown',name:'Lat pulldown',group:'Back'},{id:'seated-row',name:'Seated row',group:'Back'},{id:'shoulder-press',name:'Shoulder press',group:'Shoulders'},{id:'leg-curl',name:'Leg curl',group:'Legs'}],sets:[]};
let state,storageError='';try{state=JSON.parse(localStorage.getItem(KEY))||structuredClone(initial);if(!Array.isArray(state.machines)||!Array.isArray(state.sets))throw Error('Invalid saved data');}catch(e){state=structuredClone(initial);storageError='Your saved data could not be loaded. Please keep this window open; saving is disabled to protect any existing data.';}
let view='list',selected=null,query='',group='All',weight='',reps='',offlineReady=false;
const root=document.querySelector('#app');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDay=t=>{const d=new Date(t);return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;};
const isToday=t=>localDay(t)===localDay(Date.now());
function save(next){if(storageError){toast('Storage unavailable. Your set was not saved.');return false;}try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch(e){toast('Could not save. Check your device storage and try again.');return false;}}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
function machineSets(){return state.sets.filter(s=>s.machine===selected&&s.person===state.person);}
function format(s){return `${s.weight} ${s.unit}${s.reps!==null?' × '+s.reps+' reps':''}`;}
function dateLabel(t){if(isToday(t))return 'Today';return new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric',year:new Date(t).getFullYear()!==new Date().getFullYear()?'numeric':undefined});}
function header(){return `<header><div class="brand"><span class="mark" aria-hidden="true">Ⅱ</span>setmate<span style="color:var(--lime)">.</span></div><button class="icon-button" data-action="info" aria-label="App and installation information">ⓘ</button></header>`;}
function people(){return `<div class="people" aria-label="Workout profile">${['You','Mabel'].map(p=>`<button data-person="${p}" class="${state.person===p?'active':''}" aria-pressed="${state.person===p}">${p}</button>`).join('')}</div>`;}
function footer(){return `<div class="foot"><span class="dot"></span><span>${offlineReady?'Ready offline · Saved on this device':'Saved on this device'}</span></div>`;}
function render(){if(view==='list')renderList();else if(view==='detail')renderDetail();else if(view==='add')renderAdd();else renderInfo();}
function listMarkup(){const filtered=state.machines.filter(m=>(group==='All'||m.group===group)&&m.name.toLowerCase().includes(query.toLowerCase()));return `<div class="section-row"><h2>Your machines</h2><span class="count">${filtered.length} machines</span></div><div class="machine-list">${filtered.map(m=>{const last=state.sets.filter(s=>s.machine===m.id&&s.person===state.person).at(-1);return `<button class="machine" data-machine="${esc(m.id)}"><span class="machine-code" aria-hidden="true">${esc(m.name.split(' ').map(w=>w[0]).slice(0,2).join('').toUpperCase())}</span><span class="machine-content"><strong>${esc(m.name)}</strong><small>${last?esc(format(last))+' · '+esc(dateLabel(last.time)):esc(m.group)+' · No sets yet'}</small></span><span class="chevron" aria-hidden="true">›</span></button>`;}).join('')||'<div class="empty">No machines found.<br>Try another filter or add a machine.</div>'}</div>`;}
function renderList(){root.innerHTML=header()+`<div class="eyebrow">Your workout, at a glance</div><h1>Let’s get a set in.</h1>`+people()+`${storageError?`<p class="error">${esc(storageError)}</p>`:''}<div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Find a machine" aria-label="Filter machines by name" value="${esc(query)}"></div><div class="chips" aria-label="Filter by muscle group">${['All',...new Set(state.machines.map(m=>m.group))].map(g=>`<button data-group="${esc(g)}" class="${group===g?'active':''}" aria-pressed="${group===g}">${esc(g)}</button>`).join('')}</div><div id="list-results">${listMarkup()}</div><button class="add" data-action="add">＋ Add a machine</button>`+footer();}
function renderDetail(){const m=state.machines.find(m=>m.id===selected);const sets=machineSets();const today=sets.filter(s=>isToday(s.time));const previous=sets.filter(s=>!isToday(s.time));const last=previous.at(-1);const lastSets=last?previous.filter(s=>localDay(s.time)===localDay(last.time)):[];root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">${esc(m.group)}</div><h1>${esc(m.name)}</h1>`+people()+`<div class="last"><div class="last-label"><strong>Last workout · ${esc(state.person)}</strong><span>${last?esc(dateLabel(last.time)):''}</span></div>${last?`<div class="last-sets">${lastSets.map(s=>`<button data-repeat="${s.id}" aria-label="Use ${esc(format(s))}">${esc(format(s))}</button>`).join('')}</div><p class="hint">Tap a set to use those numbers again.</p>`:`<p class="sub" style="margin:0">No previous workout yet. Your first set starts here.</p>`}</div><form id="set-form"><div class="entry"><div class="label-row"><label for="weight">Weight</label><div class="units">${['lb','kg'].map(u=>`<button type="button" data-unit="${u}" class="${state.unit===u?'active':''}" aria-pressed="${state.unit===u}">${u}</button>`).join('')}</div></div><div class="stepper"><button type="button" data-step="weight:-5" aria-label="Decrease weight by 5">−</button><input id="weight" name="weight" type="text" inputmode="decimal" placeholder="0" autocomplete="off" aria-label="Weight in ${state.unit}" value="${esc(weight)}" required><button type="button" data-step="weight:5" aria-label="Increase weight by 5">＋</button></div></div><div class="entry"><div class="label-row"><label for="reps">Reps <span class="optional">optional</span></label><button type="button" class="undo" data-action="clear-reps">Clear</button></div><div class="stepper"><button type="button" data-step="reps:-1" aria-label="Decrease reps by 1">−</button><input id="reps" name="reps" type="text" inputmode="numeric" placeholder="—" autocomplete="off" aria-label="Reps, optional" value="${esc(reps)}"><button type="button" data-step="reps:1" aria-label="Increase reps by 1">＋</button></div></div><button class="primary" type="submit">＋ Log set for ${esc(state.person)}</button></form><section class="today"><div class="section-row"><h2>Today’s sets</h2><span class="count">${today.length} ${today.length===1?'set':'sets'}</span></div>${today.map((s,i)=>`<div class="set-row"><span class="set-num">${String(i+1).padStart(2,'0')}</span><span class="set-detail">${esc(format(s))}<br><small>${new Date(s.time).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</small></span><button class="undo" data-remove="${s.id}" aria-label="Remove set ${i+1}">Remove</button></div>`).join('')||'<p class="sub">No sets logged today. Ready when you are.</p>'}</section>`+footer();}
function renderAdd(){root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">Make it yours</div><h1>Add a machine.</h1><form id="machine-form" class="form"><label>Machine name<input name="name" placeholder="e.g. Cable row" maxlength="80" required autocomplete="off"></label><label>Muscle group<select name="group">${['Legs','Chest','Back','Shoulders','Arms','Core','Other'].map(g=>`<option>${g}</option>`).join('')}</select></label><button class="primary" type="submit">Add machine</button></form>`+footer();}
function renderInfo(){root.innerHTML=header()+`<button class="back" data-action="back">‹ All machines</button><div class="eyebrow">Always in your corner</div><h1>Your pocket log.</h1><div class="notice"><strong>Install on iPhone</strong><ol><li>Open this app’s link in Safari.</li><li>Tap Share, then <strong>Add to Home Screen</strong>.</li><li>Keep <strong>Open as Web App</strong> enabled if shown, then tap Add.</li></ol></div><div class="notice"><strong>Saved here, for you.</strong><p>Machines and sets stay on this device. You and Mabel have separate histories. Nothing is sent to a server, and devices don’t sync.</p><p>Clearing website data removes your log. The Home Screen app may have separate storage from Safari and this preview; log real workouts in the installed app.</p><p id="offline-info">${offlineReady?'Ready to use offline.':'Loading offline files. Keep the app open until it’s ready.'}</p></div>`+footer();}
function preload(){const last=machineSets().at(-1);weight=last?String(last.weight):'';reps=last&&last.reps!==null?String(last.reps):'';if(last&&last.unit!==state.unit)save({...state,unit:last.unit});}
root.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.querySelector('#list-results').innerHTML=listMarkup();}if(e.target.id==='weight')weight=e.target.value;if(e.target.id==='reps')reps=e.target.value;});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.person){if(save({...state,person:d.person})){if(view==='detail')preload();render();}}else if(d.machine){selected=d.machine;view='detail';preload();render();window.scrollTo(0,0);}else if(d.group){group=d.group;render();}else if(d.action){if(d.action==='back'){view='list';render();window.scrollTo(0,0);}if(d.action==='add'){view='add';render();}if(d.action==='info'){view='info';render();}if(d.action==='clear-reps'){reps='';document.querySelector('#reps').value='';}}else if(d.unit){const next=d.unit;if(next!==state.unit&&weight.trim()!==''&&Number.isFinite(Number(weight))){weight=String(Math.round(Number(weight)*(next==='kg'?0.45359237:2.20462262)*10)/10);}if(save({...state,unit:next}))render();}else if(d.step){const [field,delta]=d.step.split(':');let value=Number(field==='weight'?weight:reps)||0;value=Math.max(field==='reps'?1:0,Math.round((value+Number(delta))*10)/10);if(field==='weight')weight=String(value);else reps=String(value);document.querySelector('#'+field).value=value;}else if(d.repeat){const s=state.sets.find(s=>s.id===d.repeat);weight=String(s.weight);reps=s.reps===null?'':String(s.reps);save({...state,unit:s.unit});render();toast('Numbers ready. Tap Log set to save.');}else if(d.remove){if(save({...state,sets:state.sets.filter(s=>s.id!==d.remove)})){render();toast('Set removed');}}});
root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='machine-form'){const f=new FormData(e.target);const name=f.get('name').trim();if(!name){toast('Enter a machine name');return;}if(state.machines.some(m=>m.name.toLowerCase()===name.toLowerCase())){toast('That machine is already on your list');return;}if(save({...state,machines:[...state.machines,{id:crypto.randomUUID(),name,group:f.get('group')}]})){view='list';query='';group='All';render();toast('Machine added');}}else if(e.target.id==='set-form'){const w=Number(weight.trim().replace(',','.'));const r=reps.trim()===''?null:Number(reps);if(weight.trim()===''||!Number.isFinite(w)||w<0||w>10000){toast('Enter a weight from 0 to 10,000');return;}if(r!==null&&(!Number.isInteger(r)||r<1||r>999)){toast('Enter whole reps from 1 to 999, or leave blank');return;}const s={id:crypto.randomUUID(),machine:selected,person:state.person,weight:w,reps:r,unit:state.unit,time:new Date().toISOString()};if(save({...state,sets:[...state.sets,s]})){weight=String(w);render();toast('Set saved for '+state.person);}}});
render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;const f=document.querySelector('.foot span:last-child');if(f)f.textContent='Ready offline · Saved on this device';const info=document.querySelector('#offline-info');if(info)info.textContent='Ready to use offline.';}).catch(()=>{const info=document.querySelector('#offline-info');if(info)info.textContent='Offline setup failed. Reopen the app while online to try again.';});}
